mapper.select:
/*selectBuyerMdAmAdminAgentSearchList*/ SELECT A.COM_NAME_LOC AS COM_NAME_LOC, A.IRS_NO AS IRS_NO, A.TEL_NO AS TEL_NO, A.CEO_NAME_LOC AS CEO_NAME_LOC, A.BUSINESS_ITEMS AS BUSINESS_ITEMS, A.COM_CODE AS AGENT_CODE FROM ICOMCMPY A, (SELECT DISTINCT AGENT FROM ICOMCQDT WHERE BUYER = #{st_buyer_org_code} AND STATUS <> 'D') B WHERE A.BUSINESS_COND = 'S' AND A.COM_CODE = B.AGENT AND A.STATUS IN ('C','R') AND A.ADD_DATE BETWEEN #{fromDate} AND #{toDate}
AND A.COM_NAME_LOC LIKE '%'||#{st_agent_name}||'%'
ORDER BY COM_NAME_LOC

/*selectBuyerMdAmAdminAgentSearchExcel*/ SELECT DISTINCT A.COM_NAME_LOC AS COM_NAME_LOC, A.IRS_NO AS IRS_NO, A.ZIP_CODE AS ZIP_CODE, A.ADDRESS_LOC AS ADDRESS_LOC, A.CEO_NAME_LOC AS CEO_NAME_LOC, A.INDUSTRY_TYPE AS INDUSTRY_TYPE, A.BUSINESS_ITEMS AS BUSINESS_ITEMS, DECODE(A.COUNTRY_CODE,'KR','Korea, Republic of',A.COUNTRY_CODE) AS COUNTRY_CODE, A.ESTABLISH_DATE, A.TEL_NO, A.FAX_NO, A.HP_ADDRESS, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE COM_CODE = A.COM_CODE AND USER_TYPE = 'A' AND ROWNUM = 1) AS SALES_PERSON, (SELECT PHONE_NUMBER FROM ICOMLUSR WHERE COM_CODE = A.COM_CODE AND USER_TYPE = 'A' AND ROWNUM = 1) AS SALES_TEL, (SELECT FAX_NUMBER FROM ICOMLUSR WHERE COM_CODE = A.COM_CODE AND USER_TYPE = 'A' AND ROWNUM = 1) AS SALES_FAX, (SELECT MOBILE_PHONE FROM ICOMLUSR WHERE COM_CODE = A.COM_CODE AND USER_TYPE = 'A' AND ROWNUM = 1) AS SALES_MOBILE, (SELECT EMAIL FROM ICOMLUSR WHERE COM_CODE = A.COM_CODE AND USER_TYPE = 'A' AND ROWNUM = 1) AS SALES_EMAIL, '' AS ITMG1_NM, '' AS ITMG2_NM, '' AS ITMG3_NM, '' AS ITMG4_NM, '' AS ITMG5_NM
FROM ICOMCMPY A, SUPLINFO2 S WHERE A.COM_CODE = S.SUPPLIER AND A.BUSINESS_COND = 'S' AND A.STATUS IN ('C','R') AND A.ADD_DATE BETWEEN #{fromDate} AND #{toDate}
AND A.COM_NAME_LOC LIKE '%'||#{st_agent_name}||'%'
AND A.COM_CODE IN (SELECT DISTINCT AGENT FROM ICOMCQDT WHERE BUYER = #{st_buyer_org_code} AND STATUS <> 'D') ORDER BY A.COM_NAME_LOC
